"""Vingt recherches facultatives utilisant les outils expliqués dans le livre."""
from dataclasses import dataclass
from modele import Q
@dataclass
class Defi:
    titre:str
    enonce:str
    indices:list
    corrige:str
    controle:str
    figure:str=''
DEFIS=[
Defi('Une commande au meilleur prix',
r'On commande 18 carnets. A vend chaque carnet 2,40 euros avec 5 euros de frais par commande. B vend des lots de cinq à 10 euros, sans frais. On peut acheter plus de carnets que nécessaire. Déterminer la commande la moins chère.',
['Combien de lots de cinq faut-il pour en avoir au moins 18 ?','Comparer les deux dépenses totales, en ajoutant les frais une seule fois.'],
r'\editionEtape{Traduire les offres}Chez A : $18\times2{,}40+5=48{,}20$ euros. Chez B : trois lots donnent seulement 15 carnets ; il en faut quatre, soit 20 carnets pour 40 euros.\editionEtape{Comparer}La commande chez B coûte $\res{8{,}20}$ euros de moins et laisse deux carnets supplémentaires. Acheter exactement 18 carnets n’était pas une obligation ; c’est ce qui change le choix.',
'assert 18*Rational("2.4")+5==Rational("48.2") and ceil(Rational(18,5))*10==40'),
Defi('Deux restes et une divisibilité',
r'Trouver tous les entiers entre 100 et 150 qui laissent un reste de 2 dans la division par 7 et sont divisibles par 9. Expliquer pourquoi la liste est complète.',
['Lister les multiples de 9 dans l’intervalle.','Tester le reste de la division par 7 pour chacun.'],
r'\editionEtape{Réduire les candidats}Les multiples de 9 sont $108,117,126,135,144$.\editionEtape{Tester la seconde condition}Leurs restes par 7 sont respectivement $3,5,0,2,4$. Seul $\res{135}$ convient : $135=7\times19+2$.\editionEtape{Complétude}La première liste contient tous les multiples de 9 de l’intervalle ; chaque candidat a été testé. Il n’y a donc pas d’autre solution.',
'assert [a for a in range(100,151) if a%7==2 and a%9==0]==[135]'),
Defi('Un nombre et son opposé',
r'On cherche un nombre $a$ dont la distance à zéro est strictement comprise entre 2 et 5, et dont l’opposé est strictement négatif. Donner tous les entiers possibles, puis deux solutions décimales.',
[r'Si l’opposé est strictement négatif, de quel signe est $a$ ?','Pour un nombre positif, la distance à zéro est le nombre lui-même.'],
r'\editionEtape{Utiliser le signe}Si $-a<0$, alors $a$ est strictement positif. Sa distance à zéro, sa valeur absolue, est donc $a$ lui-même.\editionEtape{Combiner les contraintes}On obtient $2<a<5$. Les entiers possibles sont $\res{3\text{ et }4}$. Deux décimaux possibles sont $\res{2{,}5\text{ et }4{,}8}$. Les bornes 2 et 5 sont exclues.',
'assert [a for a in range(-8,9) if 2<Abs(a)<5 and -a<0]==[3,4]'),
Defi('Remonter un carnet de bord',
r'Un sous-marin part d’une altitude inconnue. Il descend de 35 m, remonte de 18,5 m puis descend de 7,5 m. Il termine à $-64$ m. Trouver son altitude de départ et la variation totale.',
['Calculer la somme des trois variations.','Le départ est la valeur finale moins la variation totale.'],
r'\editionEtape{Bilan des déplacements}La variation totale vaut $-35+18{,}5-7{,}5=\res{-24\ \mathrm m}$.\editionEtape{Retrouver le départ}L’altitude initiale vaut $-64-(-24)=\res{-40\ \mathrm m}$.\editionEtape{Contrôler}Depuis $-40$, on passe à $-75$, puis $-56{,}5$, puis $-64$ m. La variation et l’altitude finale ne sont pas la même grandeur.',
'assert -35+Rational("18.5")-Rational("7.5")==-24 and -64-(-24)==-40'),
Defi('Une fraction entre deux autres',
r'Trouver tous les entiers positifs $a$ tels que $3/5<a/15<4/5$. Parmi les fractions obtenues, lesquelles ont une écriture décimale finie ? Justifier par une écriture équivalente ou par la division.',
['Écrire les deux bornes avec le dénominateur 15.','Tester les numérateurs strictement entre 9 et 12.'],
r'\editionEtape{Encadrer le numérateur}$3/5=9/15$ et $4/5=12/15$, donc $9<a<12$. Les solutions sont $\res{a=10\text{ et }11}$.\editionEtape{Étudier les écritures}$10/15=2/3$ donne une division qui se répète ; $11/15=0{,}7333\ldots$ aussi. Aucune des deux n’a d’écriture décimale finie. Une approximation finie ne doit pas être confondue avec une égalité exacte.',
'assert [a for a in range(1,20) if Rational(3,5)<Rational(a,15)<Rational(4,5)]==[10,11]'),
Defi('Un ruban en trois parts',
r'A reçoit $2/7$ d’un ruban ; B reçoit $1/3$ du ruban initial. C reçoit les 32 cm restants. Trouver la longueur initiale et les trois parts.',
['Calculer la fraction restante avec le dénominateur 21.','32 cm correspondent à huit parts élémentaires.'],
r'\editionEtape{Une fraction du tout}$1-2/7-1/3=21/21-6/21-7/21=8/21$.\editionEtape{Retrouver le tout}Huit vingt-et-unièmes valent 32 cm, donc un vingt-et-unième vaut 4 cm. Le ruban mesure $\res{84\ \mathrm{cm}}$.\editionEtape{Répartir}A reçoit 24 cm, B 28 cm, C 32 cm. Le contrôle $24+28+32=84$ confirme le partage.',
'assert 1-Rational(2,7)-Rational(1,3)==Rational(8,21) and 32//8*21==84 and 24+28+32==84'),
Defi('Le cadre autour d’un carré',
r'Un carré de côté 8 cm est entouré d’une bordure extérieure de 1 cm. Retrouver l’aire de la bordure par deux méthodes, sans la compter deux fois aux coins.',
['Soustraire deux aires de carrés.','Découper en quatre bandes de 8 cm sur 1 cm et quatre petits carrés de 1 cm de côté.'],
r'\editionEtape{Par différence}Le côté extérieur est 10 cm ; $10^2-8^2=\res{36\ \mathrm{cm}^2}$.\editionEtape{Par découpage}Quatre bandes donnent $4\times8\times1=32$ cm$^2$ ; les quatre coins ajoutent 4 cm$^2$. Total : 36 cm$^2$.\editionEtape{Éviter un piège}Quatre bandes de 10 cm sur 1 cm compteraient les coins deux fois.',
'assert 10**2-8**2==4*8*1+4*1**2==36','puiss-15'),
Defi('Retrouver l’étape d’un motif',
r'Une rangée de carrés accolés utilise $3n+1$ allumettes à l’étape $n$. Peut-on utiliser exactement 100 allumettes ? Et 101 ? Donner une procédure arithmétique.',
['Retirer l’allumette supplémentaire.','Le nombre restant doit pouvoir se partager en groupes de trois.'],
r'\editionEtape{Pour 100}Après retrait de 1, il reste 99, soit 33 groupes de trois. L’étape $\res{33}$ convient.\editionEtape{Pour 101}Il reste 100, qui n’est pas divisible par 3 : aucune étape entière ne convient.\editionEtape{Procédure}Pour un total donné, retirer 1 puis tester la divisibilité par 3. Il faut aussi que l’étape obtenue soit au moins 1.',
'assert 3*33+1==100 and (101-1)%3!=0','lit-8'),
Defi('La somme de cinq consécutifs',
r'Exprimer la somme de cinq entiers consécutifs en fonction du premier $n$, puis montrer qu’elle est cinq fois celui du milieu.',
['Écrire les nombres n, n+1, n+2, n+3, n+4.','Réduire la somme puis chercher le facteur 5.'],
r'\editionEtape{Exprimer}La somme vaut $n+(n+1)+(n+2)+(n+3)+(n+4)=5n+10$.\editionEtape{Factoriser}$5n+10=5(n+2)$. Or $n+2$ est le troisième nombre, celui du milieu.\editionEtape{Conclure}La somme est toujours $\res{cinq\ fois\ le\ nombre\ du\ milieu}$. La lettre rend l’argument valable pour tous les entiers, au-delà d’exemples particuliers.',
'assert expand(sum(n+k for k in range(5)))==expand(5*(n+2))'),
Defi('Un partage dessiné',
r'Trois parts identiques et 6 euros supplémentaires donnent 45 euros. Si on ajoute ensuite 5 euros à chacune des trois parts, quel nouveau total obtient-on ? Expliquer deux méthodes.',
['Retrouver la valeur d’une part.','On peut aussi ajouter directement trois fois cinq au total initial.'],
r'\editionEtape{Retrouver les parts}Les parts seules totalisent $45-6=39$ euros, donc chaque part vaut 13 euros.\editionEtape{Première méthode}La nouvelle part vaut 18 euros ; avec le supplément inchangé, $3\times18+6=\res{60}$ euros.\editionEtape{Seconde méthode}On ajoute trois fois 5 euros : $45+15=60$. Les deux raisonnements donnent le même résultat.',
'assert (45-6)//3==13 and 3*(13+5)+6==45+3*5==60','eq-14'),
Defi('Deux réductions successives',
r'Un article coûte 100 euros. On retire d’abord 20 % du prix, puis 10 % du nouveau prix. Est-ce une réduction totale de 30 % ? Justifier et déterminer la réduction totale.',
['La seconde réduction porte sur 80 euros.','Comparer le prix final au prix initial.'],
r'\editionEtape{Calculer les étapes}Après 20 %, le prix vaut 80 euros. Les 10 % suivants valent 8 euros ; le prix final est $\res{72}$ euros.\editionEtape{Comparer}La réduction totale vaut $100-72=28$ euros sur 100, soit $\res{28\,\%}$. Additionner 20 % et 10 % ne convient pas car les références sont différentes.',
'assert 100*(1-Rational(20,100))*(1-Rational(10,100))==72'),
Defi('Un modèle et son domaine',
r'Une réserve de 24 L perd 3 L par minute. Déterminer les volumes aux minutes 3 et 7, le moment où elle est vide, puis expliquer ce que ferait un tableur si on continuait la formule après ce moment.',
['Utiliser 24-3t.','Une réserve ne peut pas avoir un volume négatif.'],
r'\editionEtape{Calculer}À 3 minutes, il reste 15 L ; à 7 minutes, 3 L. Elle est vide à $\res8$ minutes.\editionEtape{Interpréter}Le tableur continuerait de calculer $24-3t$, donnant $-3$ L à 9 minutes. Le calcul est possible mais ne décrit plus le volume réel. Le modèle doit être arrêté à huit minutes.',
'assert 24-3*3==15 and 24-3*7==3 and 24-3*8==0 and 24-3*9==-3','rep-15'),
Defi('Quatre angles et une bissectrice',
r'Autour de O, quatre angles consécutifs valent $110^\circ$, $95^\circ$, une mesure inconnue et $80^\circ$. On trace la bissectrice de l’angle inconnu. Calculer chacune de ses moitiés et expliquer pourquoi les autres angles ne changent pas.',
['Un tour vaut 360 degrés.','Partager seulement l’angle concerné en deux.'],
r'\editionEtape{Reconstituer l’angle}Il vaut $360-110-95-80=75^\circ$.\editionEtape{Partager}La bissectrice donne $\res{37{,}5^\circ}$ de chaque côté. Elle ajoute une demi-droite à l’intérieur de l’angle, sans déplacer ses côtés ni ceux des autres angles.',
'assert Rational(360-110-95-80,2)==Rational("37.5")','ang-13'),
Defi('Une aire en plusieurs partages',
r'ABC a une base AB de 12 cm et une hauteur issue de C de 5 cm. M est le milieu de [AB]. N est le milieu de [AM]. Trouver les aires de ACM, ACN et NCM sans calculer de nouvelle hauteur.',
['Les triangles ont la même hauteur issue de C.','Leurs bases sur (AB) valent 6, 3 et 3 cm.'],
r'\editionEtape{Grande aire}ABC a une aire de 30 cm$^2$.\editionEtape{Première médiane}CM partage cette aire en deux : ACM a une aire de $\res{15\ \mathrm{cm}^2}$.\editionEtape{Deuxième partage}CN est une médiane du triangle ACM. ACN et NCM ont chacun une aire de $\res{7{,}5\ \mathrm{cm}^2}$. Les aires se déduisent des bases égales et de la hauteur commune.',
'assert Rational(12*5,2)==30 and Rational(6*5,2)==15 and Rational(3*5,2)==Rational("7.5")','defi-triangle-partages'),
Defi('Un triangle et son centre',
r'On applique un demi-tour de centre O au triangle donné. Montrer que le quadrilatère AB A′B′, pris dans cet ordre, est un parallélogramme, à condition que A, B et O ne soient pas alignés.',
['Quel est le milieu de [AA′] ? Et de [BB′] ?','Ce sont les deux diagonales du quadrilatère indiqué.'],
r'\editionEtape{Identifier les diagonales}Dans le quadrilatère A-B-A′-B′, les diagonales sont [AA′] et [BB′].\editionEtape{Utiliser le demi-tour}O est le milieu des deux segments.\editionEtape{Conclure}Les diagonales ont le même milieu, donc le quadrilatère est un $\res{parallélogramme}$. La condition de non-alignement exclut un quadrilatère aplati.',
'assert (2+(-2))/2==0 and (1+(-1))/2==0 and expand(2*x-x)==x','sym-7'),
Defi('Même base, plusieurs aires',
r'Un parallélogramme a une base de 8 cm et une hauteur de 3 cm. On déplace le côté supérieur parallèlement à la base sans changer la hauteur ni la base. L’aire change-t-elle ? Le périmètre doit-il rester identique ?',
['L’aire dépend de la base et de la hauteur.','La longueur des côtés obliques peut changer.'],
r'\editionEtape{Aire}Elle reste $8\times3=\res{24\ \mathrm{cm}^2}$ : la formule ne dépend pas du décalage horizontal.\editionEtape{Périmètre}Il n’est pas nécessairement conservé, car les côtés obliques peuvent s’allonger. Par exemple, un rectangle de base 8 et de hauteur 3 a des côtés latéraux de 3 ; après décalage non nul, ils dépassent 3.\editionEtape{Conclusion}Conserver une aire ne suffit pas à conserver un périmètre.',
'assert 8*3==24 and sqrt(1**2+3**2)>3','para-4'),
Defi('Deux cylindres de même capacité',
r'Un cylindre A a un rayon de 2 cm et une hauteur de 10 cm. Un cylindre B a un rayon de 4 cm. Quelle hauteur doit avoir B pour contenir le même volume ? Comparer les hauteurs.',
['Écrire le volume exact de A.','L’aire de base de B est quatre fois celle de A.'],
r'\editionEtape{Volume de référence}$V_A=\pi\times2^2\times10=40\pi$ cm$^3$.\editionEtape{Aire de base de B}Elle vaut $16\pi$ cm$^2$, quatre fois $4\pi$.\editionEtape{Hauteur}Pour le même volume, la hauteur est divisée par quatre : $10:4=\res{2{,}5\ \mathrm{cm}}$. Contrôle : $16\pi\times2{,}5=40\pi$.',
'assert pi*2**2*10==pi*4**2*Rational("2.5")','sol-7'),
Defi('Une moyenne à atteindre',
r'Quatre notes sont 8, 12, 13 et 15. On ajoute une cinquième note. Quelle note donne une moyenne de 13 ? Quelle moyenne maximale peut-on atteindre si chaque note est au plus 20 ?',
['Une moyenne de 13 sur cinq notes exige une somme de 65.','Pour maximiser la moyenne, prendre la cinquième note égale à 20.'],
r'\editionEtape{Atteindre 13}La somme connue vaut 48. Il faut $65-48=\res{17}$.\editionEtape{Maximum}Avec 20, la somme vaut 68 et la moyenne $68:5=\res{13{,}6}$. Toute note plus petite donnerait une somme et une moyenne plus petites.',
'assert 5*13-(8+12+13+15)==17 and Rational(8+12+13+15+20,5)==Rational("13.6")'),
Defi('Deux conditions pour une urne',
r'Une urne comporte 20 boules rouges, bleues ou vertes. La probabilité de rouge est $1/4$, celle de bleu $2/5$. Combien faut-il de boules de chaque couleur ? Vérifier que le modèle est possible.',
['Trouver séparément les effectifs rouge et bleu.','Les boules restantes seront vertes.'],
r'\editionEtape{Effectifs connus}Un quart de 20 vaut 5 rouges ; deux cinquièmes valent 8 bleues.\editionEtape{Compléter}Il reste $20-5-8=\res7$ vertes.\editionEtape{Vérifier}Les effectifs sont entiers positifs et totalisent 20. Les probabilités sont $5/20=1/4$, $8/20=2/5$, $7/20$, de somme 1.',
'assert Rational(1,4)*20==5 and Rational(2,5)*20==8 and 20-5-8==7'),
Defi('Un escalier en boucle',
r'Le script de l’escalier répète trois fois : avancer de 30, tourner à gauche de 90 degrés, avancer de 20, tourner à droite de 90 degrés. Modifier seulement le nombre de répétitions pour finir 150 pas à droite et 100 pas en haut. Donner la distance totale parcourue.',
['Chaque répétition ajoute 30 à droite et 20 en haut.','Le nombre de répétitions doit convenir aux deux déplacements.'],
r'\editionEtape{Déterminer la répétition}$150:30=5$ et $100:20=5$ : il faut $\res5$ répétitions.\editionEtape{Distance parcourue}Chaque motif a une longueur de $30+20=50$ pas, donc le lutin parcourt $\res{250}$ pas.\editionEtape{Distinguer les grandeurs}La longueur du trajet en escalier n’est pas la distance en ligne droite entre départ et arrivée.',
'assert 5*30==150 and 5*20==100 and 5*(30+20)==250','prog-12'),
]
